public class DebuggerRmiRegistersProviderTest : AbstractDebuggerRegistersProviderTest {

	protected TraceObject setUpRmiTarget()
    {
		createRmiConnection();
		addRegisterMethods();
		using (Transaction tx = tb.startTransaction())
{
			tb.createObjectsProcessAndThreads();
			tb.createObjectsFramesAndRegs(
				tb.obj("Processes[1].Threads[1]").queryInterface(typeof(TraceThread)),
				Lifespan.nowOn(0), tb.host, 2);
		}
		rmiCx.publishTarget(tool, tb.trace);
		traceManager.openTrace(tb.trace);
		traceManager.activateTrace(tb.trace);
		return Objects.requireNonNull(tb.obj("Processes[1]"));
	}

	/* @Test */
	public void testReadLiveValuesOnActivate()
    {
		setUpRmiTarget();
		waitForSwing();

		handleReadRegsInvocation(tb.obj("Processes[1].Threads[1].Stack[0].Registers"), () => null);
	}

	/* @Test */
	public void testModifyValueLive()
    {
		setUpRmiTarget();
		waitForSwing();

		controlService.setCurrentMode(tb.trace, ControlMode.RW_TARGET);

		assertTrue(registersProvider.actionEnableEdits.isEnabled());
		performAction(registersProvider.actionEnableEdits);

		RegisterRow row = findRegisterRow(r0);

		setRowText(row, "1234");
		handleWriteRegInvocation(
			tb.obj("Processes[1].Threads[1].Stack[0]").queryInterface(typeof(TraceStackFrame)),
			"r0", 0x1234);
	}

	/* @Test */
